(()=>{'use strict';const el=id=>document.getElementById(id),day=86400000;let hist,exp,view='replay',timer=null,days=[],daily=[],series={},times=[],index=0,chosenDay='',horizon=3,metric='rain';const nf=(v,n=3)=>v==null?'Missing':v.toFixed(n);const utc=t=>new Date(t).toISOString().slice(0,10);const stamp=t=>new Date(t).toLocaleString('en-GB',{timeZone:'Europe/London',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});const color=v=>`hsl(164 35% ${96-v*65}%)`;
function stop(){if(timer){clearInterval(timer);timer=null;}const b=el('play-replay');if(b)b.textContent='▶ Play';}
function makeDaily(){const ds=hist.series.diglis.readings;const start=Math.floor(Date.parse(ds[0].dateTime)/day)*day,end=Math.floor(Date.parse(ds.at(-1).dateTime)/day)*day;for(let t=start;t<=end;t+=day){const row={date:utc(t),t};for(const k of ['diglis','bewdley','rain']){const vals=hist.series[k].readings.filter(r=>Date.parse(r.dateTime)>=t&&Date.parse(r.dateTime)<t+day).map(r=>r.value).filter(Number.isFinite);row[k]={n:vals.length,min:vals.length?Math.min(...vals):null,max:vals.length?Math.max(...vals):null,total:vals.reduce((a,b)=>a+b,0)};}daily.push(row);}days=daily.map(r=>r.date);}
function rangeRows(){return chosenDay?times.filter(t=>utc(t)===chosenDay):times;}
function svgLines(rows,cursor){const start=rows[0],end=rows.at(-1);if(rows.length<2)return '<p>Not enough readings.</p>';const W=920,left=55,right=895;let out='<svg viewBox="0 0 920 320" role="img" aria-label="Two river-level charts with a linked time cursor">';const x=t=>left+(t-start)/(end-start)*(right-left);['diglis','bewdley'].forEach((k,j)=>{const vals=rows.filter(t=>series[k].has(t)).map(t=>series[k].get(t)),lo=Math.min(...vals),hi=Math.max(...vals),pad=Math.max(.005,(hi-lo)*.12),min=lo-pad,max=hi+pad,top=30+j*145,bottom=125+j*145,y=v=>bottom-(v-min)/(max-min)*90;out+=`<text x="55" y="${top-10}" font-size="12" fill="#496a61">${k==='diglis'?'Diglis':'Bewdley'} · metres above its own datum</text>`;for(let i=0;i<3;i++){const v=min+(max-min)*i/2;out+=`<path d="M55 ${y(v)}H895" stroke="#e4e9df"/><text x="47" y="${y(v)+4}" text-anchor="end" font-size="11" fill="#5b706b">${v.toFixed(2)}</text>`;}let path='',prev=null;for(const t of rows){if(!series[k].has(t))continue;path+=(prev===null||t-prev>1800000?'M':'L')+x(t)+','+y(series[k].get(t))+' ';prev=t;}out+=`<path d="${path}" fill="none" stroke="${j?'#b87e3d':'#27756a'}" stroke-width="2.5"/><path d="M${x(cursor)} ${top-4}V${bottom}" stroke="#183c38" stroke-dasharray="4 3"/>`;if(series[k].has(cursor))out+=`<circle cx="${x(cursor)}" cy="${y(series[k].get(cursor))}" r="5" fill="${j?'#b87e3d':'#27756a'}" stroke="white" stroke-width="2"/>`;});out+=`<text x="55" y="310" font-size="12" fill="#5b706b">${stamp(start)}</text><text x="895" y="310" text-anchor="end" font-size="12" fill="#5b706b">${stamp(end)}</text></svg>`;return out;}
function updateReplay(){const ts=rangeRows();index=Math.max(0,Math.min(index,ts.length-1));const t=ts[index];el('replay-time').textContent=stamp(t)+' UK time';el('replay-time').setAttribute('datetime',new Date(t).toISOString());el('time-range').value=index;el('time-range').setAttribute('aria-valuetext',stamp(t));el('replay-diglis').textContent=nf(series.diglis.get(t))+' m';el('replay-bewdley').textContent=series.bewdley.has(t)?nf(series.bewdley.get(t))+' m':'Missing';const rain=[];for(let i=0;i<4;i++)rain.push(series.rain.get(t-i*900000));el('replay-rain').textContent=rain.every(Number.isFinite)?nf(rain.reduce((a,b)=>a+b,0),1)+' mm':'Incomplete';el('replay-chart').innerHTML=svgLines(ts,t);}
function replay(){const ts=rangeRows();index=Math.min(index,ts.length-1);el('explorer-body').innerHTML=`<h3>Scrub through the recorded river</h3><p class="data-label">Move the slider or press Play. Both gauges follow the same timestamp, with separate vertical scales.</p><div class="explore-tools"><label>Period <select id="replay-day"><option value="">Whole snapshot</option>${days.map(d=>`<option value="${d}" ${d===chosenDay?'selected':''}>${d}</option>`).join('')}</select></label><button id="play-replay">▶ Play</button><time id="replay-time"></time></div><input class="replay-slider" id="time-range" type="range" min="0" max="${ts.length-1}" step="1" value="${index}" aria-label="Recorded observation time"><div class="replay-stats"><div class="replay-stat"><span>DIGLIS · TARGET GAUGE</span><strong id="replay-diglis"></strong></div><div class="replay-stat"><span>BEWDLEY · UPSTREAM</span><strong id="replay-bewdley"></strong></div><div class="replay-stat"><span>LOCAL RAIN · PRECEDING HOUR</span><strong id="replay-rain"></strong></div></div><div class="viz-scroll" id="replay-chart"></div><p class="inspect-note">The cursor replays observations; it does not simulate a flood. Missing data stays missing. A higher number at one gauge does not mean the water surface is higher than at the other.</p>`;el('replay-day').onchange=e=>{stop();chosenDay=e.target.value;index=0;replay();};el('time-range').oninput=e=>{stop();index=Number(e.target.value);updateReplay();};el('play-replay').onclick=()=>{if(timer){stop();return;}if(index>=ts.length-1)index=0;el('play-replay').textContent='Ⅱ Pause';timer=setInterval(()=>{index+=Math.max(1,Math.ceil(ts.length/120));if(index>=ts.length-1){index=ts.length-1;stop();}updateReplay();},200);};updateReplay();}
function calendar(){const values=daily.map(r=>metric==='rain'?(r.rain.n===96?r.rain.total:null):r.diglis.max);const max=Math.max(...values.filter(v=>v!=null),.001),min=metric==='rain'?0:Math.min(...values.filter(v=>v!=null));el('explorer-body').innerHTML=`<div class="section-head"><h3>A day-by-day view of the snapshot</h3><label>Colour by <select id="calendar-metric"><option value="rain" ${metric==='rain'?'selected':''}>Daily local rainfall</option><option value="level" ${metric==='level'?'selected':''}>Daily Diglis maximum</option></select></label></div><p class="data-label">Each tile is one UTC day, ordered from left to right. Tap a day to replay it. Grey rainfall tiles have incomplete coverage, not zero rain.</p><div class="calendar-legend"><span>${nf(min,2)} ${metric==='rain'?'mm':'m'}</span><div class="gradient"></div><span>${nf(max,2)} ${metric==='rain'?'mm':'m'}</span></div><div class="day-grid">${daily.map((r,i)=>{const v=values[i],ratio=v==null?0:(v-min)/(max-min||1);return `<button class="day-cell" data-date="${r.date}" style="background:${v==null?'#e5e6e2':color(ratio)};color:${ratio>.8?'white':'#163c38'}" title="${r.date}: ${v==null?'incomplete':v.toFixed(3)}; Diglis ${r.diglis.n}/96, rainfall ${r.rain.n}/96 readings"><span>${r.date.slice(5)}</span><strong>${v==null?'—':v.toFixed(metric==='rain'?1:3)} ${metric==='rain'?'mm':'m'}</strong><small>${metric==='rain'?(r.rain.n===96?'Complete day':r.rain.n+'/96 readings'):(r.diglis.n===96?'Complete day':'Partial day')}</small></button>`;}).join('')}</div><button id="daily-export">Download daily summary CSV ↓</button><p class="inspect-note">Daily maxima are the largest observed values, not guaranteed daily peaks. Rain totals are shown only for complete 96-reading UTC days. The latest day may still be in progress.</p>`;el('calendar-metric').onchange=e=>{metric=e.target.value;calendar();};document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{chosenDay=b.dataset.date;index=0;switchView('replay');});el('daily-export').onclick=()=>download('daily-summary.csv','date_utc,diglis_readings,diglis_min_m,diglis_max_m,rain_readings,rain_total_mm_complete_days_only\n'+daily.map(r=>[r.date,r.diglis.n,r.diglis.min,r.diglis.max,r.rain.n,r.rain.n===96?r.rain.total:''].join(',')).join('\n'));}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function microscope(){const r=exp.results.find(r=>r.horizon===horizon);if(!r){el('explorer-body').textContent='No experiment results available.';return;}const vals=r.trace.flatMap(p=>[p.actual,p.model]),lo=Math.min(...vals)-.005,hi=Math.max(...vals)+.005,scale=v=>55+(v-lo)/(hi-lo)*310,yy=v=>355-(v-lo)/(hi-lo)*310;let scatter='<svg viewBox="0 0 410 410" role="img" aria-label="Experimental prediction versus observed level. Points on the diagonal are exact predictions.">';for(let i=0;i<4;i++){const v=lo+(hi-lo)*i/3;scatter+=`<path d="M55 ${yy(v)}H365 M${scale(v)} 45V355" stroke="#e1e8de"/><text x="${scale(v)}" y="375" text-anchor="middle" font-size="10">${v.toFixed(2)}</text><text x="47" y="${yy(v)+3}" text-anchor="end" font-size="10">${v.toFixed(2)}</text>`;}scatter+='<path d="M55 355L365 45" stroke="#65766b" stroke-dasharray="5 4"/>';r.trace.forEach(p=>{scatter+=`<circle cx="${scale(p.actual)}" cy="${yy(p.model)}" r="3.5" fill="#27756a" opacity=".55"><title>${stamp(p.time*1000)}: actual ${p.actual.toFixed(3)} m, prediction ${p.model.toFixed(3)} m</title></circle>`;});scatter+='<text x="210" y="400" text-anchor="middle" font-size="12">Observed level (m)</text><text x="15" y="210" transform="rotate(-90 15 210)" text-anchor="middle" font-size="12">Predicted level (m)</text></svg>';const errors=r.trace.map(p=>(p.model-p.actual)*100),limit=Math.max(.1,...errors.map(Math.abs)),bins=Array(12).fill(0);errors.forEach(e=>bins[Math.min(11,Math.floor((e+limit)/(2*limit)*12))]++);let bars='<svg viewBox="0 0 410 300" role="img" aria-label="Prediction error distribution in centimetres. Negative means too low; positive means too high.">';const maxCount=Math.max(...bins);bins.forEach((n,i)=>{const a=-limit+i*limit/6,b=a+limit/6,h=n/maxCount*180;bars+=`<rect x="${40+i*28}" y="${225-h}" width="25" height="${h}" fill="${i<6?'#729d98':'#c29155'}"><title>${a.toFixed(2)} to ${b.toFixed(2)} cm: ${n} predictions</title></rect>`;});bars+=`<path d="M40 225H376" stroke="#abb8ac"/><text x="40" y="245" font-size="11">−${limit.toFixed(2)} cm</text><text x="208" y="245" text-anchor="middle" font-size="11">0</text><text x="376" y="245" text-anchor="end" font-size="11">+${limit.toFixed(2)} cm</text><text x="40" y="278" font-size="12">Too low ← prediction error → Too high</text><text x="40" y="20" font-size="12">Bar height: count (largest bin = ${maxCount})</text></svg>`;const abs=errors.map(Math.abs).sort((a,b)=>a-b),p90=abs[Math.ceil(abs.length*.9)-1],bias=errors.reduce((a,b)=>a+b,0)/errors.length;el('explorer-body').innerHTML=`<div class="section-head"><h3>Look beyond the average error</h3><label>Horizon <select id="micro-horizon">${[1,3,6].map(h=>`<option value="${h}" ${h===horizon?'selected':''}>${h} hour${h>1?'s':''} ahead</option>`).join('')}</select></label></div><p class="data-label">Same held-out predictions as the experiment below. These charts describe the upstream + local rain model.</p><div class="insight-strip"><div><strong>${errors.length}</strong><span>Held-out predictions</span></div><div><strong>${p90.toFixed(2)} cm</strong><span>90th percentile absolute error</span></div><div><strong>${bias>0?'+':''}${bias.toFixed(2)} cm</strong><span>Average signed error</span></div></div><div class="micro-grid"><div><h3>Predicted vs observed</h3><div class="viz-scroll">${scatter}</div><p class="data-label">Both axes have the same scale. Closer to the dashed diagonal means a closer prediction.</p></div><div><h3>Where the errors fall</h3><div class="viz-scroll">${bars}</div><p class="data-label">Negative errors underestimate the observed level; positive errors overestimate it.</p></div></div><details><summary>Inspect exact predictions</summary><div class="table-wrap"><table><thead><tr><th>Target time (UK)</th><th>Observed m</th><th>Predicted m</th><th>Error cm</th></tr></thead><tbody>${r.trace.map(p=>`<tr><td>${stamp(p.time*1000)}</td><td>${p.actual.toFixed(3)}</td><td>${p.model.toFixed(3)}</td><td>${((p.model-p.actual)*100).toFixed(2)}</td></tr>`).join('')}</tbody></table></div></details><button id="prediction-export">Download these predictions ↓</button><p class="inspect-note">Small errors during quiet river conditions do not establish flood-event skill. The 90th percentile is a sample statistic, not a future guarantee or confidence interval.</p>`;el('micro-horizon').onchange=e=>{horizon=Number(e.target.value);microscope();};el('prediction-export').onclick=()=>download('diglis-'+horizon+'h-predictions.csv','target_time_utc,actual_m,predicted_m,error_cm\n'+r.trace.map(p=>[new Date(p.time*1000).toISOString(),p.actual,p.model,(p.model-p.actual)*100].join(',')).join('\n'));}
function quality(){el('explorer-body').innerHTML='<h3>Can we trust the coverage?</h3><p class="data-label">Daily observations received, against 96 expected 15-minute slots per UTC day. Bars show completeness, not water level.</p>'+['diglis','bewdley','rain'].map(k=>`<h3>${k==='rain'?'Local rainfall 1773':k==='diglis'?'Diglis':'Bewdley'}</h3><div class="quality-bars">${daily.map(r=>`<button class="quality-bar" data-quality="${r.date}" style="height:${Math.max(2,Math.min(100,r[k].n/96*100))}%;background:${r[k].n===96?'#27756a':'#c29155'}" aria-label="${r.date}: ${r[k].n} of 96 readings. Open day replay." title="${r.date}: ${r[k].n}/96 readings"></button>`).join('')}</div><div class="quality-key"><span>${days[0]}</span><span>${days.at(-1)}</span></div>`).join('')+`<p class="inspect-note">Teal = 96 readings; amber = incomplete or unexpected count. Coverage alone does not establish sensor accuracy. Near-real-time observations can be revised; this is not yet the quality-qualified historical archive.</p><details><summary>Daily coverage table</summary><div class="table-wrap"><table><thead><tr><th>UTC date</th><th>Diglis /96</th><th>Bewdley /96</th><th>Rain /96</th></tr></thead><tbody>${daily.map(r=>`<tr><td>${r.date}</td><td>${r.diglis.n}</td><td>${r.bewdley.n}</td><td>${r.rain.n}</td></tr>`).join('')}</tbody></table></div></details>`;document.querySelectorAll('[data-quality]').forEach(b=>b.onclick=()=>{chosenDay=b.dataset.quality;index=0;switchView('replay');});}
function switchView(v){stop();view=v;document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));({replay,calendar,accuracy:microscope,quality}[view])();}
Promise.all(['history.json','experiment.json'].map(p=>fetch(p).then(r=>{if(!r.ok)throw Error('Snapshot unavailable');return r.json();}))).then(([h,e])=>{hist=h;exp=e;for(const k of ['diglis','bewdley','rain'])series[k]=new Map(hist.series[k].readings.filter(r=>Number.isFinite(r.value)).map(r=>[Date.parse(r.dateTime),r.value]));times=[...series.diglis.keys()].sort((a,b)=>a-b);makeDaily();el('explorer-source').textContent=`${days.length} UTC dates · ${days[0]} to ${days.at(-1)} · captured ${stamp(Date.parse(hist.retrievedAt))} UK time. Explore this saved sample below.`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>switchView(b.dataset.view));switchView('replay');}).catch(()=>{el('explorer-source').textContent='Research snapshot unavailable. Please reload or use the source links below.';});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});})();
